nde figuur in het gezin, krijgt opnieuw betekenis. Iris Murdoch onderzoekt hoe een terugkeer oude rollen kan activeren en hoe moeilijk het is werkelijk buiten een familiegeschiedenis te gaan staan.","source_type":"official_catalog","source_name":"Gecontroleerde boek- en catalogusbronnen","source_url":"https://openlibrary.org/works/OL1326316W","evidence":[{"type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p801993296"],"checked_at":"2026-11-02T19:34:00.000Z","reference":"work:3202","note":"IrisMurdoch TheItalianGirl1964, exact Querido/Salamander paperback. No new identity from full-name authorityJeanIrisMurdoch.","canonical_name_resolution":null},{"type":"original_substantive_source_review","review":"content-review-031.json","sources":["https://openlibrary.org/works/OL1326316W","https://data.bibliotheken.nl/id/nbt/p801993296"]},{"type":"cover_front_review","cover_id":6964827,"sha256":"07f770a2347e22734928aea5ab196fcf71a87a5dd56c5c1cf098c461b645e4eb","reference":"cover-semantic-review-010.json","limitation":"Actually read cover-large/sheet-003.jpg. Iris Murdoch; Het Italiaanse meisje; Salamander. Front identity and source-edition attachment are corroboration, not proof of a visible barcode, printing year, language or complete contents. Bibliographic checks remain separate."}],"provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-11-02T19:34:00.000Z","review_batch":"nl-scale-20261102-010"}},{"ref":"m6","relation":"catalog_edition_metadata","key":{"edition_id":987209006},"before":null,"after":{"edition_id":987209006,"work_id":987109004,"bound_author_id":987309004,"bound_title":"Het Italiaanse Meisje","bound_language":"dut","bound_isbn13":"9789021494029","format":"paperback","cover_url":"https://covers.openlibrary.org/b/id/6964827-L.jpg?default=false","card_cover_url":"https://covers.openlibrary.org/b/id/6964827-M.jpg?default=false","evidence_url":"https://data.bibliotheken.nl/id/nbt/p801993