ity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p099981157","http://data.bibliotheken.nl/id/nbt/p377510343"],"checked_at":"2026-11-02T19:34:00.000Z","reference":"work:5073","note":"Hermans1993fictional wartime diary/Boekenweek novella. Same ISBN appears on two source-edition keys: reuse exact current record and bound front, never add another edition.","canonical_name_resolution":null},{"type":"original_substantive_source_review","review":"content-review-032.json","sources":["https://openlibrary.org/works/OL15253352W","https://data.bibliotheken.nl/id/nbt/p099981157","https://data.bibliotheken.nl/id/nbt/p377510343"]},{"type":"cover_front_review","cover_id":6453533,"sha256":"f55f9373fee7426e8a8c9d7744e5e5cbebebf6f766a5bb9a1fb00d47d63d4352","reference":"cover-semantic-review-010.json","limitation":"Actually read cover-large/sheet-001.jpg. Willem Frederik Hermans; In de mist van het schimmenrijk; diary-fragment subtitle visible. Front identity and source-edition attachment are corroboration, not proof of a visible barcode, printing year, language or complete contents. Bibliographic checks remain separate."}],"provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-11-02T19:34:00.000Z","review_batch":"nl-scale-20261102-010"}},{"ref":"m7","relation":"catalog_edition_metadata","key":{"edition_id":987209010},"before":null,"after":{"edition_id":987209010,"work_id":987109008,"bound_author_id":969300005,"bound_title":"In de mist van het schimmenrijk","bound_language":"dut","bound_isbn13":"9789074336024","format":"paperback","cover_url":"https://covers.openlibrary.org/b/id/6453533-L.jpg?default=false","card_cover_url":"https://covers.openlibrary.org/b/id/6453533-M.jpg?default=false","evidence_url":"https://data.bibliotheken.nl/id/nbt/p099981157","evidence":[{"type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p099981157","http://data.bibliotheken.nl/id/nbt/p377510343"],"checked_at":